// Configuração de busca CNPJ
// CNAE 6911-7/01 = Serviços advocatícios
// APIs públicas: BrasilAPI, ReceitaWS, CNPJ.ws

const config = {
  cnae: '6911701',
  targetStates: $input.first().json.states || ['SP'],
  apiProvider: 'brasilapi', // brasilapi, receitaws, cnpjws
  batchSize: 50,
  // Filtros de porte
  porteFilter: ['03', '05'], // 03=Pequena, 05=Media
  // 01=Micro, 03=Pequena, 05=Media, 09=Grande
};

return [{ json: config }];

// Query BrasilAPI for CNAE-based company search
// BrasilAPI: https://brasilapi.com.br/api/cnpj/v1/{cnpj}
// For bulk search, use casadosdados.com.br or similar
//
// Strategy:
// 1. Use public CNPJ search APIs that support CNAE filtering
// 2. Filter by state, porte, and active status
// 3. Deduplicate against existing leads

const existingCnpjs = new Set(
  ($input.first().json || []).map(r => r.cnpj).filter(Boolean)
);

// Casa dos Dados API (free, public CNPJ search)
// Allows CNAE + state + porte filtering
const searchUrl = 'https://api.casadosdados.com.br/v2/cnpj';
const config = $('Configure CNPJ Search').first().json;

return [{
  json: {
    searchUrl,
    config,
    existingCount: existingCnpjs.size,
    query: {
      'query': {
        'termo': [],
        'atividade_principal': [config.cnae],
        'natureza_juridica': [],
        'uf': config.targetStates,
        'municipio': [],
        'bairro': [],
        'situacao_cadastral': 'ATIVA',
        'cep': [],
        'ddd': []
      },
      'range_query': {
        'data_abertura': { 'lte': null, 'gte': null },
        'capital_social': { 'lte': null, 'gte': 50000 }
      },
      'extras': {
        'somente_mei': false,
        'excluir_mei': true,
        'com_email': true,
        'incluir_atividade_secundaria': false,
        'com_contato_telefonico': false,
        'somente_fixo': false,
        'somente_celular': false,
        'somente_matriz': true
      },
      'page': 1
    }
  }
}];

// Transform CNPJ results into lead format
// Dedup: filter out already-ingested CNPJs
const response = $input.first().json;
const existingCnpjs = new Set(
  ($('Fetch Existing CNPJs').first().json || []).map(r => r.cnpj).filter(Boolean)
);
const allCompanies = response.body?.cnpj || response.data || [];
const companies = allCompanies.filter(c => {
  const cnpj = c.cnpj || c.cnpj_basico || '';
  return cnpj && !existingCnpjs.has(cnpj);
});
console.log(`Dedup: ${allCompanies.length} total, ${companies.length} new (${allCompanies.length - companies.length} skipped)`);

const leads = companies.map(company => {
  // Extract primary partner/owner name
  const socios = company.qsa || company.socios || [];
  const mainSocio = socios.find(s => 
    s.qual_socio === 'Sócio-Administrador' || 
    s.qualificacao_socio?.includes('Administrador') ||
    s.qualificacao_socio?.includes('Diretor')
  ) || socios[0] || {};

  const socioName = mainSocio.nome_socio || mainSocio.nome || '';
  const nameParts = socioName.split(' ');

  return {
    json: {
      first_name: nameParts[0] || company.razao_social?.split(' ')[0] || 'N/A',
      last_name: nameParts.slice(1).join(' ') || '',
      email: company.email || null,
      phone: company.ddd_telefone_1 ? `${company.ddd_telefone_1}` : null,
      company_name: company.razao_social || company.nome_fantasia || null,
      company_website: null,
      company_size: mapPorte(company.porte || company.descricao_porte),
      industry: 'legal',
      role: mainSocio.qualificacao_socio || 'Socio',
      source: 'cnpj_receita',
      status: 'new',
      tags: ['cnpj-enrichment', company.uf || 'unknown'],
      custom_fields: {
        cnpj: company.cnpj || company.cnpj_basico || null,
        razao_social: company.razao_social || null,
        nome_fantasia: company.nome_fantasia || null,
        uf: company.uf || null,
        municipio: company.municipio || null,
        capital_social: company.capital_social || null,
        data_abertura: company.data_inicio_atividade || company.data_abertura || null,
        cnae_principal: company.cnae_fiscal || null,
        porte: company.porte || company.descricao_porte || null,
        num_socios: socios.length,
        scraped_at: new Date().toISOString()
      }
    }
  };
}).filter(l => l.json.first_name !== 'N/A');

function mapPorte(porte) {
  if (!porte) return null;
  const p = porte.toLowerCase();
  if (p.includes('micro')) return 'micro';
  if (p.includes('pequen')) return 'small';
  if (p.includes('medi') || p.includes('médio')) return 'medium';
  if (p.includes('grand')) return 'large';
  return null;
}

console.log(`Transformed ${leads.length} CNPJ records into leads`);
return leads;

